head.script:
scwin.trigger1_onclick = function(e) {
	wframe1.setSrc("/sample/common_link/wframe_treeView_customFormatter_WPFF-340_(WSQ-3843)_sub.xml");
};

// WPFF-340: scope=true wframe 의 treeView customFormatter(scwin 함수) 적용 노드 수
scwin.countFormattedNode = function() {
	var tree = document.getElementById($p.id + "wframe1_treeview1");
	if (!tree) {
		return -1;
	}
	return (tree.innerText.match(/ Scope formatter/g) || []).length;
};
